-- IPA SG official past questions: 2016 autumn morning, questions 31-40.
-- Questions/options are from the published IPA paper; answers checked against the official key.
-- Official question PDF: https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf
-- Official answer key: https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_ans.pdf
INSERT OR IGNORE INTO questions
(id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language)
VALUES
('sg-official-h28a-2016-q31','exam-sg','法務・プロバイダ責任制限法','standard','single_choice','【2016年度 平成28年秋期 午前 問31】プロバイダ責任制限法において，損害賠償責任が制限されるプロバイダの行為に該当するものはどれか。','[{"id":"a","text":"契約書に記載された利用者の個人情報を，本人の同意なく関連会社に渡した。"},{"id":"b","text":"他のプロバイダに移転する利用者に，不当に高い違約金を請求した。"},{"id":"c","text":"利用者の送信メールを盗聴し，興味本位で他人に伝えた。"},{"id":"d","text":"利用者の電子掲示板への書込みが他人の権利を侵害しているとは知らずに放置した。"}]','"d"','正解はエ。権利侵害を知らず，かつ知ることができたと認められる相当の理由がない場合など，掲示板管理者等の責任が制限されることがある。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q32','exam-sg','法務・電子計算機使用詐欺','standard','single_choice','【2016年度 平成28年秋期 午前 問32】刑法の電子計算機使用詐欺罪が適用される違法行為はどれか。','[{"id":"a","text":"ねずみ講方式による取引形態のWebページを開設する。"},{"id":"b","text":"実際より良品と誤認させる商品カタログを掲載し，粗悪な商品を販売する。"},{"id":"c","text":"インターネット経由で銀行システムに虚偽の情報を与え，不正な振込や送金をさせる。"},{"id":"d","text":"企業のWebページを不正に改変し，その企業の信用を傷つける情報を流す。"}]','"c"','正解はウ。コンピュータに虚偽の情報を与えて財産権の得喪・変更に関わる不実の電磁的記録を作り，不正送金を行う行為は電子計算機使用詐欺に該当し得る。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q33','exam-sg','個人情報・マイナンバー','standard','single_choice','【2016年度 平成28年秋期 午前 問33】特定個人情報ファイルの取扱いについて，事業者向けガイドラインで認められているものはどれか。','[{"id":"a","text":"個人番号関係事務が不要となり，法令上の保存期間を過ぎた場合も，暗号化して保管する。"},{"id":"b","text":"事務取扱担当者を限定せず，従業員全員にアクセス権を設定する。"},{"id":"c","text":"従業員の個人番号を含む源泉徴収票の作成を，業務委託先の税理士に依頼する。"},{"id":"d","text":"従業員の個人番号を使って営業成績を管理する。"}]','"c"','正解はウ。法令で認められる個人番号関係事務を委託する場合，委託先を適切に監督することを前提に源泉徴収票の作成等を依頼できる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q34','exam-sg','法務・特定電子メール法','standard','single_choice','【2016年度 平成28年秋期 午前 問34】広告宣伝の電子メールを送信する場合，特定電子メール法に照らして適切なものはどれか。','[{"id":"a","text":"許諾を通知する手段をメールに表示すれば，同意を得ていない不特定多数に送信できる。"},{"id":"b","text":"同意を得ていない不特定多数に送信する場合，表題に未承諾広告と明示すればよい。"},{"id":"c","text":"取引関係などの例外を除き，あらかじめ送信に同意した者だけに送信するオプトイン方式をとる。"},{"id":"d","text":"メールアドレスを自動生成する場合は，送信者の氏名・連絡先を明示すれば同意は不要である。"}]','"c"','正解はウ。広告宣伝メールは原則として事前同意を得た相手に送るオプトイン方式が求められる（一部例外あり）。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q35','exam-sg','法務・不正アクセス禁止法','standard','single_choice','【2016年度 平成28年秋期 午前 問35】不正アクセス禁止法による処罰の対象となる行為はどれか。','[{"id":"a","text":"推測されやすいパスワードの実例を，セミナー資料に掲載した。"},{"id":"b","text":"ネットサーフィン中に意図せず他人のIDとパスワードを取得し，PCに保存した。"},{"id":"c","text":"親族になりすまし，不正送金のための口座番号を指定するメールを送った。"},{"id":"d","text":"不正アクセスを行う目的で他人の利用者IDとパスワードを取得したが，まだ不正アクセスは行っていない。"}]','"d"','正解はエ。不正アクセスを行う目的で他人の識別符号を取得する行為自体が，法の処罰対象となり得る。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q36','exam-sg','契約・準委任契約','standard','single_choice','【2016年度 平成28年秋期 午前 問36】準委任契約の説明はどれか。','[{"id":"a","text":"成果物の対価として報酬を得る契約"},{"id":"b","text":"成果物を完成させる義務を負う契約"},{"id":"c","text":"善良な管理者の注意義務を負って作業を受託する契約"},{"id":"d","text":"発注者の指揮命令下で作業を行う契約"}]','"c"','正解はウ。準委任契約は業務の遂行を委託する契約で，受託者は善管注意義務を負う。成果物完成義務が中心の請負契約とは異なる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q37','exam-sg','ISMS・内部監査','standard','single_choice','【2016年度 平成28年秋期 午前 問37】JIS Q 27001に準拠してISMSを運用している場合，内部監査について順守すべき要求事項はどれか。','[{"id":"a","text":"監査員に，ISMS認証機関が認定する研修修了者を含めなければならない。"},{"id":"b","text":"監査責任者は代表取締役が任命しなければならない。"},{"id":"c","text":"監査範囲はJIS Q 27001に規定された管理策に限定しなければならない。"},{"id":"d","text":"監査プログラムでは，前回までの監査結果を考慮しなければならない。"}]','"d"','正解はエ。内部監査プログラムは，対象プロセスの重要性や前回監査の結果などを考慮して計画する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q38','exam-sg','デジタルフォレンジックス','standard','single_choice','【2016年度 平成28年秋期 午前 問38】インシデント調査やシステム監査にも利用できる，証拠を収集し保全する技法はどれか。','[{"id":"a","text":"コンティンジェンシープラン"},{"id":"b","text":"サンプリング"},{"id":"c","text":"ディジタルフォレンジックス"},{"id":"d","text":"ベンチマーキング"}]','"c"','正解はウ。デジタルフォレンジックスは電子的証拠を適切に収集・保全・分析し，調査や監査に利用する技法である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q39','exam-sg','事業継続計画・BCP監査','standard','single_choice','【2016年度 平成28年秋期 午前 問39】事業継続計画（BCP）について監査を実施した結果，適切な状況と判断されるものはどれか。','[{"id":"a","text":"従業員の緊急連絡先リストを作成し，最新版に更新している。"},{"id":"b","text":"重要書類を複製せず，1か所で集中保管している。"},{"id":"c","text":"全ての業務について優先順位を付けず，同一水準のBCPを策定している。"},{"id":"d","text":"平時にはBCPを従業員に非公開としている。"}]','"a"','正解はア。緊急連絡先を最新に保つことは，災害時の迅速な連絡・対応に必要なBCP対策である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q40','exam-sg','情報セキュリティ監査基準','standard','single_choice','【2016年度 平成28年秋期 午前 問40】「情報セキュリティ監査基準」に関する記述のうち，最も適切なものはどれか。','[{"id":"a","text":"情報セキュリティ監査基準は，ISMSの国際規格と同一内容で策定・更新されている。"},{"id":"b","text":"情報セキュリティ監査人は，他の専門家の支援を受けてはならない。"},{"id":"c","text":"情報セキュリティ監査の判断尺度には，原則として情報セキュリティ管理基準を用いる。"},{"id":"d","text":"監査人には高度な技術的専門性が求められるため，独立性は不要である。"}]','"c"','正解はウ。情報セキュリティ監査では，監査の判断尺度として情報セキュリティ管理基準を用いることが原則である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja');
